#include <bits/stdc++.h>
using namespace std;

struct DSU {
    vector<int> p, r;
    DSU(int n) {
        p.resize(n + 1);
        r.resize(n + 1, 0);
        iota(p.begin(), p.end(), 0);
    }
    int find(int x) {
        return p[x] == x ? x : p[x] = find(p[x]);
    }
    bool unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) return false;
        if (r[a] < r[b]) swap(a, b);
        p[b] = a;
        if (r[a] == r[b]) r[a]++;
        return true;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M, K;
    cin >> N >> M >> K;

    DSU dsu1(N);
    int C = N;
    bool ok = true;
    vector<pair<int, int>> type2;

    for (int i = 0; i < M; ++i) {
        int a, b, t;
        cin >> a >> b >> t;
        if (t == 1) {
            if (!dsu1.unite(a, b)) {
                ok = false;
            } else {
                --C;
            }
        } else {
            type2.emplace_back(a, b);
        }
    }

    if (!ok) {
        cout << "N\n";
        return 0;
    }

    DSU dsu2(N);
    int cc2 = C;

    for (auto &e : type2) {
        int a = e.first, b = e.second;
        int ra = dsu1.find(a);
        int rb = dsu1.find(b);
        if (ra != rb) {
            if (dsu2.unite(ra, rb)) {
                --cc2;
            }
        }
    }

    int M2 = (int)type2.size();
    int omitted = M2 - C + cc2;

    if (omitted <= K) {
        cout << "S\n";
    } else {
        cout << "N\n";
    }

    return 0;
}
